    copy(out, v) {
        out[0] = v[0];
        out[1] = v[1];
        return out;
    }

    /**
     * @function LevelRenderer.Tool.Vector.prototype.set
     * @description 设置向量的两个项。
     *
     * @param {Vector2} out - 基础向量。
     * @param {number} a - 项 a。
     * @param {number} b - 项 b。
     * @return {Vector2} 结果。
     */
    set(out, a, b) {
        out[0] = a;
        out[1] = b;
        return out;
    }

    /**
     * @function LevelRenderer.Tool.Vector.prototype.add
     * @description 向量相加。
     *
     * @param {Vector2} out - 基础向量。
     * @param {Vector2} v1 - 向量 v1。
     * @param {Vector2} v2 - 向量 v2。
     * @return {Vector2} 结果。
     */
    add(out, v1, v2) {
        out[0] = v1[0] + v2[0];
        out[1] = v1[1] + v2[1];
        return out;
    }

