 const CommontypesConversion_isArray = function(obj) {
  return Object.prototype.toString.call(obj) == '[object Array]';
}
/**
 * @class CommontypesConversion
 * @category BaseTypes Util
 * @classdesc Leaflet 对象和 SuperMap 对象转换工具。
 * @usage
 */
const CommontypesConversion = {
    /**
     * @function CommontypesConversion.toSuperMapBounds
     * @description 将 Leaflet 对象的 bounds 转成 SuperMap 的 bounds对象。
     * @param {(L.Bounds|L.LatLngBounds)} bounds - 图层显示范围。
     * @returns {Bounds} SuperMap 的 bounds 对象。
     */
    toSuperMapBounds(bounds) {
        if (!bounds) {
            return new Bounds();
        }
        if (bounds instanceof Bounds) {
            return bounds;
        }
        if (GeoJSON.getGeoJSONType(bounds)) {
            bounds = external_L_default().geoJSON(bounds).getBounds();
        }
        if (bounds instanceof (external_L_default()).LatLngBounds) {
            const southWest = bounds.getSouthWest();
            const northEast = bounds.getNorthEast();
            return new Bounds(
                southWest.lng,
                southWest.lat,
                northEast.lng,
                northEast.lat
            );
        }
        if (bounds instanceof (external_L_default()).Bounds) {
            return new Bounds(
                bounds.min.x,
                bounds.min.y,
                bounds.max.x,
                bounds.max.y
            );
        }
        if (CommontypesConversion_isArray(bounds) && bounds.length >= 4) {
            return new Bounds(
                bounds[0],
                bounds[1],
                bounds[2],
                bounds[3]
            );
        }

        return new Bounds();
    },

    /**
     * @function CommontypesConversion.isArray
     * @description 判断是否为数组格式。
     * @param {Object} obj - 待判断的对象。
     * @returns {boolean} 是否是数组。
     */
    isArray: CommontypesConversion_isArray,

    /**
     * @function CommontypesConversion.toProcessingParam
     * @description 将 Region 节点数组转为 Processing 服务需要的分析参数。
     * @param {Array} points - Region 各个节点数组。
     * @returns processing 服务裁剪、查询分析的分析参数。
     */
      toProcessingParam(points) {
        var geometryParam = {};
        if (points.length < 1) {
            geometryParam = "";
        } else {
            var results = [];
            for (var i = 0; i < points.length; i++) {
                var point = {};
                point.x = points[i][0];
                point.y = points[i][1];
                results.push(point);
            }
            geometryParam.type = "REGION";
            geometryParam.points = results;
        }
        return geometryParam;
    }
}


